const MIN_TRACKS = 4;
const ROOT_FOLDER_ID = 'YOUR_GOOGLE_DRIVE_ROOT_FOLDER_ID';
const rows = $input.all().map((item) => item.json);
const groups = {};

for (const row of rows) {
  const status = String(row.Status ?? row.status ?? '').trim().toLowerCase();
  const genre = String(row.Genre ?? row.genre ?? '').trim();
  const trackId = String(row.Track_ID ?? row.track_id ?? '').trim();
  if (status !== 'pending' || !genre || !trackId) continue;

  const safeGenre = genre.replace(/[^\p{L}\p{N}\s_-]/gu, '-').replace(/\s+/g, ' ').trim();
  const createdAt = String(row.Created_At ?? row.created_at ?? '').trim();
  const month = /^\d{4}-\d{2}/.test(createdAt) ? createdAt.slice(0, 7) : $now.toFormat('yyyy-MM');
  const key = `${safeGenre}::${month}`;
  if (!groups[key]) groups[key] = { genre: safeGenre, month, tracks: [] };
  groups[key].tracks.push({
    trackId,
    title: String(row.Title ?? row.title ?? '').trim(),
    audioUrl: String(row.Audio_URL ?? row.audio_url ?? '').trim(),
    coverUrl: String(row.Cover_URL ?? row.cover_url ?? '').trim(),
    lyrics: String(row.Lyrics ?? row.lyrics ?? '').trim()
  });
}

return Object.values(groups)
  .filter((group) => group.tracks.length >= MIN_TRACKS)
  .map((group) => {
    const albumName = `Suno Album - ${group.genre} - ${group.month}`;
    return {
      json: {
        genre: group.genre,
        month: group.month,
        albumName,
        trackCount: group.tracks.length,
        trackIds: group.tracks.map((track) => track.trackId),
        tracks: group.tracks,
        driveQuery: `'${ROOT_FOLDER_ID}' in parents and trashed = false and mimeType = 'application/vnd.google-apps.folder' and name = '${albumName}'`
      }
    };
  });

const source = $('Find Eligible Albums').item.json;
const existing = $json;
return [{
  json: {
    ...source,
    folderId: String(existing.id ?? ''),
    folderUrl: existing.id ? `https://drive.google.com/drive/folders/${existing.id}` : '',
    folderCreated: false
  }
}];

const source = $('Resolve Album Folder').item.json;
const created = $json;
return [{
  json: {
    ...source,
    folderId: String(created.id ?? ''),
    folderUrl: created.id ? `https://drive.google.com/drive/folders/${created.id}` : '',
    folderCreated: Boolean(created.id),
    nextStep: 'Create original, master, lyrics, and metadata subfolders'
  }
}];
